/* @lc app=leetcode id=1001 lang=kotlin */

class Solution {
    fun gridIllumination(n: Int, lamps: Array<IntArray>, queries: Array<IntArray>): IntArray = HashMap<Int, Int>().let { rows -> HashMap<Int, Int>().let { cols -> HashMap<Int, Int>().let { d1 -> HashMap<Int, Int>().let { d2 -> HashSet<Long>().let { active -> lamps.forEach { lamp -> (lamp[0].toLong() * n + lamp[1]).let { key -> active.add(key).takeIf { it }?.let { rows.put(lamp[0], rows.getOrDefault(lamp[0], 0) + 1).let { cols.put(lamp[1], cols.getOrDefault(lamp[1], 0) + 1).let { d1.put(lamp[0] - lamp[1], d1.getOrDefault(lamp[0] - lamp[1], 0) + 1).let { d2.put(lamp[0] + lamp[1], d2.getOrDefault(lamp[0] + lamp[1], 0) + 1) } } } } } }.let { queries.map { query -> query[0].let { r -> query[1].let { c -> ((rows.getOrDefault(r, 0) > 0 || cols.getOrDefault(c, 0) > 0 || d1.getOrDefault(r - c, 0) > 0 || d2.getOrDefault(r + c, 0) > 0)).let { lit -> (-1..1).forEach { dr -> (-1..1).forEach { dc -> (r + dr).let { nr -> (c + dc).let { nc -> (nr.toLong() * n + nc).takeIf { nr in 0 until n && nc in 0 until n }?.let { key -> active.remove(key).takeIf { it }?.let { rows.put(nr, (rows[nr] ?: 1) - 1).let { cols.put(nc, (cols[nc] ?: 1) - 1).let { d1.put(nr - nc, (d1[nr - nc] ?: 1) - 1).let { d2.put(nr + nc, (d2[nr + nc] ?: 1) - 1) } } } } } } } } }.let { if (lit) 1 else 0 } } } }.toIntArray() } } } } } }
}}